    /** Colours a theme deliberately does not change, as the page declares them. */
    object Fixed {
        const val markPlate = 0xFFFFFFFF
    }

    /** Which set of colours a reader has chosen. */
    enum class Theme { CLASSROOM, DRACULA, INK, NORD, PAPER, PHONETIX, SILK, WINTER }

    /** What each role is worth in one theme and mode. */
    data class Palette(
        val accent: Long,
        val accentBg: Long,
        val accentInk: Long,
        val border: Long,
        val chipBg: Long,
        val chipInk: Long,
        val danger: Long,
